/**
 * OneShop role-based unit identification policy.
 * Display preferences are not authorization; callers must supply an already
 * permission-filtered view and allowed field names from trusted role grants.
 * No customer data, RO, VIN, or stock number is generated by this module.
 */
export const IDENTIFIER_FIELDS = Object.freeze({
  customer_name: 'Customer name',
  ro_number: 'RO number',
  stock_number: 'Stock number',
  vin_last6: 'VIN (last 6)',
  vin_full: 'VIN (full)',
  year_make_model: 'Year / Make / Model',
  unit_id: 'Unit reference',
});
const defaults = {
  service_writer: ['customer_name', 'ro_number'],
  technician: ['ro_number', 'vin_last6'],
  porter: ['stock_number', 'vin_last6'],
  sales: ['stock_number', 'year_make_model'],
  foreman: ['ro_number', 'vin_last6'],
  service_dispatch: ['ro_number', 'vin_last6'],
  parts: ['ro_number', 'stock_number'],
  warranty: ['ro_number', 'vin_last6'],
  pdi: ['stock_number', 'vin_last6'],
  wash: ['stock_number', 'vin_last6'],
  detail: ['stock_number', 'vin_last6'],
};
export const DEFAULT_IDENTIFIER_PROFILES = Object.freeze(
  Object.fromEntries(Object.entries(defaults).map(([role, [primary, secondary]]) =>
    [role, Object.freeze({ primary, secondary })]))
);
const clean = value => typeof value === 'string' ? value.trim() : '';
const permitted = (allowed, field) => allowed instanceof Set ? allowed.has(field) : Array.isArray(allowed) && allowed.includes(field);

export function validateIdentifierProfile(profile) {
  if (!profile || !Object.hasOwn(IDENTIFIER_FIELDS, profile.primary))
    return { ok:false, error:'Select a valid primary identifier' };
  if (profile.secondary !== 'none' && !Object.hasOwn(IDENTIFIER_FIELDS, profile.secondary))
    return { ok:false, error:'Select a valid secondary identifier' };
  if (profile.primary === profile.secondary)
    return { ok:false, error:'Primary and secondary identifiers must differ' };
  return { ok:true };
}

export function identifierValue(field, record) {
  if (!record || typeof record !== 'object') return '';
  const unit = record.unit ?? record;
  if (field === 'customer_name') return clean(record.customerName);
  if (field === 'stock_number') return clean(unit.stockNumber ?? unit.stock);
  if (field === 'vin_full') return clean(unit.vin);
  if (field === 'vin_last6') return clean(unit.vin).slice(-6);
  if (field === 'unit_id') return clean(unit.displayId ?? unit.unitId);
  if (field === 'year_make_model')
    return [unit.year, unit.make, unit.model].map(v=>clean(String(v ?? ''))).filter(Boolean).join(' ');
  if (field === 'ro_number') {
    // An active RO context is required when a unit has multiple open ROs.
    // The caller should identify its relevant RO; do not arbitrarily pick one.
    if (clean(record.roNumber)) return clean(record.roNumber);
    if (Array.isArray(record.roNumbers) && record.roNumbers.length === 1) return clean(record.roNumbers[0]);
    return '';
  }
  return '';
}

/**
 * Render a short primary/secondary identity from an authorized unit/RO view.
 * If requested fields are absent or unauthorized, only return fallbacks that
 * the permission-filtered field list explicitly permits.
 */
export function displayIdentifiers({ role, profile, record, allowedFields, fallbackFields = ['vin_last6','stock_number','unit_id'] }) {
  const selected = profile ?? DEFAULT_IDENTIFIER_PROFILES[role] ?? DEFAULT_IDENTIFIER_PROFILES.service_writer;
  const valid = validateIdentifierProfile(selected);
  if (!valid.ok) throw new Error(valid.error);
  if (!Array.isArray(allowedFields) && !(allowedFields instanceof Set))
    throw new Error('Provide authorized identifier fields');
  const fields = [selected.primary, selected.secondary, ...fallbackFields].filter(f=>f && f!=='none');
  const seen = new Set();
  const items = [];
  for (const field of fields) {
    if (seen.has(field) || !permitted(allowedFields, field) || !Object.hasOwn(IDENTIFIER_FIELDS, field)) continue;
    seen.add(field);
    const value = identifierValue(field, record);
    if (value) items.push({ field, label: IDENTIFIER_FIELDS[field], value });
    if (items.length === 2) break;
  }
  return { primary:items[0] ?? null, secondary:items[1] ?? null, needsDisambiguation:!items.length };
}

export function resolveIdentifierProfile(role, branchProfiles = {}, organizationProfiles = {}) {
  const candidate = branchProfiles?.[role] ?? organizationProfiles?.[role] ?? DEFAULT_IDENTIFIER_PROFILES[role] ?? DEFAULT_IDENTIFIER_PROFILES.service_writer;
  return validateIdentifierProfile(candidate).ok ? candidate : DEFAULT_IDENTIFIER_PROFILES[role] ?? DEFAULT_IDENTIFIER_PROFILES.service_writer;
}
